    fun={name:next(t['module'] for t in raw if t['type']=='function' and t['name']==name) for name in ['start_soon','with_timeout']}
    cocotb=common()
    for item in cocotb:
        if item['name'] in fun:item['module']=fun[item['name']]
    source_test=c.source('https://docs.cocotb.org/en/v2.1.0/writing_testbenches.html','官方2.1.0正文区分句柄与value、位宽范围、@test和真正assert；日志error本身不令测试失败。',['DUT','signal_value','stimulus','assertion'],['ValueObjectBase.get','ValueObjectBase.set','test'],['固定输入结果表定位缺失操作数/进位截断'])
