            d['packages']=[('cocotb','primary','统一信号、调度、触发器和仿真后端入口，不加入UVM/协议对象增加简单功能任务负担。')]
            syms += [co('cocotb.task','Task','cancel cancelled done result exception get_name','execute','并发任务检查与受控取消，排除弃用kill/join。','由start_soon返回真实Task。'),co('cocotb.queue','Queue','__init__','execute','协程生产消费队列。'),co('cocotb.queue','AbstractQueue','qsize empty full put put_nowait get get_nowait','execute','Queue继承的等待/状态读写，避免复制到子类。','通过Queue构造获得。'),co('cocotb._base_triggers','Event','__init__ set wait clear is_set','timing','显式事件同步，data/name为状态。'),co('cocotb._base_triggers','Lock','__init__ locked acquire release','timing','多协程共享资源同步。'),co('cocotb.types._logic_array','LogicArray','__init__ from_unsigned from_signed from_bytes to_unsigned to_signed to_bytes resolve','signal','明确位宽/符号/未知位处理，剔除弃用integer/binstr别名。'),co('cocotb.types._range','Range','__init__ from_range to_range index','signal','HDL位索引方向与Python范围互转。')]
