            d['tasks']=[recipe('repair_uvm_observed_function','由sequence发出四事务，经driver真实DUT采样；scoreboard发现漏b输出，恢复硬件控制后重建UVM树按同表复验。','固定4事务和手写输出表；不同run_test隔离配置/组件。',[('构建组件连接并发事务',refs),('采样传递结果',['cocotb.handle.ValueObjectBase.get','pyuvm._s12_uvm_tlm_interfaces.uvm_analysis_port.write','pyuvm._s13_predefined_component_classes.uvm_subscriber.write']),('修复后重建重跑',['pyuvm._s13_uvm_component.uvm_root.run_test'])],['normal覆盖和结果均通过','drop_b后functional_match=False','修复四事务均正确'],'test_hardware_verification.py:uvm function'),recipe('repair_uvm_sequence_coverage','发现vector_count=3虽已发事务均算对却漏最后一条；将配置恢复4，新run_test同时通过输入集合和输出表。','expected四事务保持，不能削减覆盖目标。',[('读取并设置事务数',['pyuvm._s13_uvm_component.ConfigDB.get','pyuvm._s13_uvm_component.ConfigDB.set']),('执行并接收',refs),('修复配置重跑',['pyuvm._s13_uvm_component.uvm_root.run_test'])],['错误仅3事务且coverage_complete=False','修复4事务','完整输出[0,3,256,510]'],'test_hardware_verification.py:uvm coverage')]
